SELECT * FROM subagent_task
WHERE execution_id=#{executionId}
ORDER BY COALESCE(updated_at, completed_at, started_at) DESC, id DESC
LIMIT #{limit}

SELECT * FROM subagent_task
WHERE agent_id=#{agentId}
ORDER BY COALESCE(updated_at, completed_at, started_at) DESC, id DESC
LIMIT #{limit}
